import csv, json

rows = list(csv.DictReader(open('input/letter_lines.csv')))

clar_subjects = {
    'addressee': 'CL-301',
    'request': 'CL-302',
    'enclosure': 'CL-303',
    'salutation': 'CL-304',
    'copies': 'CL-305',
    'delivery': 'CL-306',
    'tone': 'CL-307',
    'behavioural_plan': 'CL-308',
    'concern': 'CL-309',
}
orig_subjects = {
    'right_of_first_refusal': 'OI-202',
    'children_named': 'OI-203',
    'overnight_stays': 'OI-204',
    'inconsistent_accounts': 'OI-205',
    'sender_signature': 'OI-211',
}

def verdict_for(subject, position):
    if subject in clar_subjects:
        if subject == 'addressee':
            return 'VERIFIED' if position in {"mother", "mother's attorney"} else 'AT_ODDS'
        if subject == 'request':
            return 'VERIFIED' if position in {
                'CL match',
                'CL wording exact',
                'CL wording paraphrase',
                'no overnight stays in her care unless the father is present',
                'no overnight stays unless father present',
                'no overnight unless father present',
                'neither child overnight unless father present',
            } else 'AT_ODDS'
        if subject == 'enclosure':
            return 'VERIFIED' if position in {
                'a certified copy of the custodial plan',
                'certified',
                'certified copy',
                'certified copy enclosed',
            } else 'AT_ODDS'
        if subject == 'salutation':
            return 'VERIFIED' if position == 'Dear Counsel' else 'AT_ODDS'
        if subject == 'copies':
            return 'VERIFIED' if position in {'copy nobody', 'nobody'} else 'AT_ODDS'
        if subject == 'delivery':
            return 'VERIFIED' if position in {'by post', 'post'} else 'AT_ODDS'
        if subject == 'tone':
            return 'VERIFIED' if position == 'firm formal brief' else 'AT_ODDS'
        if subject == 'behavioural_plan':
            return 'VERIFIED' if position in {
                'confidence stability peer confidence-only',
                'full CL match',
            } else 'AT_ODDS'
        if subject == 'concern':
            return 'VERIFIED' if position in {
                'position only',
                'position limb only',
                'narrower concern only position',
            } else 'AT_ODDS'
    if subject in orig_subjects:
        if subject == 'right_of_first_refusal':
            return 'VERIFIED' if position in {
                'agreed by the father',
                'father agreed',
                'full',
            } else 'AT_ODDS'
        if subject == 'children_named':
            return 'VERIFIED' if position in {
                'both children, with their ages',
                'both children with ages',
                'both with ages',
            } else 'AT_ODDS'
        if subject == 'overnight_stays':
            return 'VERIFIED' if position in {
                'several occasions at her home or with a sitter',
                'several occasions both',
                'several occasions both children',
                'several both',
                'home or sitter both',
                'full',
            } else 'AT_ODDS'
        if subject == 'inconsistent_accounts':
            return 'VERIFIED' if position in {
                'all four',
                'all four audiences',
            } else 'AT_ODDS'
        if subject == 'sender_signature':
            return 'VERIFIED' if position in {
                "the sender's own name",
                'own name',
                'full name',
            } else 'AT_ODDS'
    return 'NOT_IN_RECORD'

out_rows = []
for r in rows:
    subject = r['subject']
    position = r['position']
    if subject in clar_subjects:
        entry = clar_subjects[subject]
        verdict = verdict_for(subject, position)
    elif subject in orig_subjects:
        entry = orig_subjects[subject]
        verdict = verdict_for(subject, position)
    else:
        entry = 'NONE'
        verdict = 'NOT_IN_RECORD'
    out_rows.append((r['line_id'], verdict, entry))

with open('letter_line_review.csv', 'w', newline='') as f:
    writer = csv.writer(f, lineterminator='\n')
    writer.writerow(['line_id', 'verdict', 'record_entry'])
    writer.writerows(out_rows)

counts = {
    'verified_count': sum(1 for _, v, _ in out_rows if v == 'VERIFIED'),
    'at_odds_count': sum(1 for _, v, _ in out_rows if v == 'AT_ODDS'),
    'not_in_record_count': sum(1 for _, v, _ in out_rows if v == 'NOT_IN_RECORD'),
    'clarification_governed_count': sum(1 for _, _, e in out_rows if e.startswith('CL-')),
}
with open('results.json', 'w') as f:
    json.dump(counts, f, indent=2)
    f.write('\n')

answer = f"""I reviewed every numbered line in the draft letter against the client's two messages, applying the review protocol so that the clarification prevails on every subject it addresses and the original instruction governs only where the clarification leaves the subject alone. Where neither record speaks to a subject, the line is not part of the verified record at all, so it cannot be sent as instructed. The draft repeatedly turns the addressee back to the father's attorney after the clarification made clear that the letter must go to the mother's attorney; it also reintroduces superseded positions on tone, concern, and the behavioural plan. Letter lines at odds with the record: {counts['at_odds_count']}. Those lines must be corrected before any version is sent, because the client's last instructions are the governing record for this letter.
"""
with open('answer.md', 'w') as f:
    f.write(answer)

print(counts)
print('rows_written', len(out_rows))
